// This file is automatically generated. Do not edit it directly.
import { createClient } from '@supabase/supabase-js';
import type { Database } from './types';
import { criarFetchSuporte, obterSuporte } from '@/lib/admin/suporte';

const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL;
const SUPABASE_PUBLISHABLE_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;

// Inclui chamadas fetch diretas das telas, sem entregar credenciais do cliente ao navegador.
const fetchSuporte = criarFetchSuporte(SUPABASE_URL, window.fetch.bind(window));
window.fetch = fetchSuporte;

// Import the supabase client like this:
// import { supabase } from "@/integrations/supabase/client";

export const supabase = createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
  global: { fetch: fetchSuporte },
  auth: {
    storage: localStorage,
    persistSession: true,
    autoRefreshToken: true,
  }
});

const getUserOriginal = supabase.auth.getUser.bind(supabase.auth);
supabase.auth.getUser = async (...args) => {
  const suporte = obterSuporte();
  return suporte ? { data: { user: suporte.user }, error: null } : getUserOriginal(...args);
};
